'use strict';

// Loads the Android web UI (android/web/index.html + ui.js) in jsdom against a stub
// bridge, so the mobile screens can be tested without a device or an emulator.
const fs = require('node:fs');
const path = require('node:path');
const { JSDOM } = require('../app/node_modules/jsdom');

const WEB = path.join(__dirname, 'web');
const HTML = fs.readFileSync(path.join(WEB, 'index.html'), 'utf8')
  // runtime.js is generated by build-web.cjs and needs the native bridge; the stub
  // below replaces window.playerAPI, so both script tags are stripped and the
  // renderer is evaluated directly.
  .replace(/<script src="[^"]+"><\/script>/g, '');

function track(overrides = {}) {
  return {
    key: 'netease:1',
    platform: 'netease',
    sourceId: '1',
    title: '晴天',
    artist: '周杰伦',
    url: 'https://music.163.com/song?id=1',
    durationMs: 269000,
    ...overrides,
  };
}

function baseState(overrides = {}) {
  const tracks = [
    track({ key: 'qq:1', platform: 'qq', sourceId: '1', title: '稻香', artist: '周杰伦', url: 'https://y.qq.com/n/ryqq/songDetail/1' }),
    track({ key: 'netease:1' }),
    track({ key: 'bilibili:1', platform: 'bilibili', sourceId: 'BV1', title: '演唱会', url: 'https://www.bilibili.com/video/BV1' }),
  ];
  return {
    tracks,
    playlists: [
      { id: 'p1', name: '通勤', queue: ['qq:1', 'netease:1'], mode: 'sequential', currentKey: null },
      { id: 'p2', name: '深夜', queue: ['bilibili:1'], mode: 'sequential', currentKey: null },
      { id: 'empty', name: '空歌单', queue: [], mode: 'sequential', currentKey: null },
    ],
    activePlaylistId: 'p1',
    playbackPlaylistId: 'p1',
    queue: ['qq:1', 'netease:1'],
    mode: 'sequential',
    currentKey: null,
    status: 'idle',
    positionMs: 0,
    durationMs: 0,
    volume: 0.7,
    muted: false,
    accounts: {},
    qualitySettings: {},
    ...overrides,
  };
}

function createMobileUi(initialState = baseState()) {
  const commands = [];
  const dom = new JSDOM(HTML, { url: 'http://localhost/', pretendToBeVisual: true, runScripts: 'outside-only' });
  const { window } = dom;

  let handler = null;
  window.playerAPI = {
    getState: async () => initialState,
    command: async (name, payload = {}) => { commands.push({ name, payload }); return { ok: true }; },
    openSource: async () => ({ ok: true }),
    getLyrics: async () => ({ ok: true, lines: [] }),
    importFile: async () => ({ ok: true }),
    exportLibrary: async () => ({ ok: true }),
    importLinks: async () => ({ ok: true }),
    login: async () => ({ ok: true }),
    search: async () => ({ ok: true, platforms: {} }),
    addSearchResult: async () => ({ ok: true }),
    playSearchResult: async () => ({ ok: true }),
    transfer: async () => ({ ok: true }),
    onState(fn) { handler = fn; return () => {}; },
    onNotice() { return () => {}; },
  };

  for(const name of ['search-match.js','sleep-timer.js','locate-playing.js','cover-background.js','background-image.js','background-settings.js'])window.eval(fs.readFileSync(path.join(WEB,'../../app/ui',name),'utf8'));
  window.eval(fs.readFileSync(path.join(WEB, 'ui.js'), 'utf8'));

  return {
    window,
    document: window.document,
    commands,
    byId: (id) => window.document.getElementById(id),
    push(state) { handler?.({ ...baseState(), ...state }); },
  };
}

const flush = () => new Promise((resolve) => setTimeout(resolve, 0));

module.exports = { createMobileUi, baseState, flush };
